import type { CSSProperties } from "react";

// Generated by strokit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-bgiwok-0 {
  stroke: var(--sk-stroke, #000000);
  stroke-dasharray: 1 1;
  animation: sk-bgiwok-t0-draw-fill calc(1800ms / var(--sk-speed, 1)) ease-in-out 0ms var(--sk-iterations, infinite) alternate both;
  animation-play-state: var(--sk-play-state, running);
}
@keyframes sk-bgiwok-t0-draw-fill {
  0% {
    stroke-dashoffset: 1;
    fill-opacity: 0;
  }
  60% {
    stroke-dashoffset: 0;
    fill-opacity: 0;
  }
  100% {
    stroke-dashoffset: 0;
    fill-opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sk-bgiwok * {
    animation: none;
  }
  .sk-bgiwok-0 {
    stroke-dashoffset: 0;
    fill-opacity: 1;
  }
}
`;

export type SupportHeartProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Apoie o strokit". */
  label?: string;
};

export function SupportHeart({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Apoie o strokit",
}: SupportHeartProps) {
  const style = {
    "--sk-speed": speed,
    "--sk-play-state": paused ? "paused" : "running",
    ...(loop === undefined ? {} : { "--sk-iterations": loop ? "infinite" : 1 }),
  } as CSSProperties;

  return (
    <svg
      viewBox="0 0 64 64"
      width={size ?? 64}
      height={size ?? 64}
      className={className ? `sk-bgiwok ${className}` : "sk-bgiwok"}
      style={style}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"Apoie"}</title>
      <path d="M32 54 C 12 40, 6 28, 12 18 C 18 8, 30 10, 32 21 C 34 10, 46 8, 52 18 C 58 28, 52 40, 32 54 Z" fill="none" stroke="#000000" strokeWidth="4" strokeLinejoin="round" pathLength="1" className="sk-bgiwok-0" />
    </svg>
  );
}
